head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30202";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30202.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// [A] 초기 목록 미해결 — jldfil30202: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_pageDataList_oncellclick
 * @description grd_pageDataList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageDataList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageDataList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageDataList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.searchDetail(r["listCertApplId"], r["bycertSeq"], r["ldMktTpCd"], r["korengTpCd"], r["listCertTpCd"], r["stkcertDelistDd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageDataList.oncellclick' });
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_SearchDetail
 * @description Search Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_SearchDetail = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_SearchDetailReq") ? $c.util.getComponent("dma_SearchDetailReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name searchDetail
 * @description search Detail 처리
 * @param {String} listCertApplId listCertApplId
 * @param {*} bycertSeq bycertSeq
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {String} korengTpCd korengTpCd
 * @param {String} listCertTpCd listCertTpCd
 * @param {String} stkcertDelistDd stkcertDelistDd
 * @returns {void}
 * @hidden N
 */
scwin.searchDetail = function (listCertApplId, bycertSeq, ldMktTpCd, korengTpCd, listCertTpCd, stkcertDelistDd) {
    let rexName;
    let dataLocation = "";
    if (listCertTpCd === "1") {
        if (ldMktTpCd === "1") {
            if (korengTpCd === "1") {
                dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=1";
                rexName = "RLDFIL00005";
            } else {
                dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=2";
                rexName = "RLDFIL00006";
            }
        } else {
            if (ldMktTpCd === "2") {
                if (korengTpCd === "1") {
                    dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=3";
                    rexName = "RLDFIL00013";
                } else {
                    dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=4";
                    rexName = "RLDFIL00014";
                }
            } else {
                if (ldMktTpCd === "6") {
                    if (korengTpCd === "1") {
                        dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=3";
                        rexName = "RLDFIL00037";
                    } else {
                        dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=4";
                        rexName = "RLDFIL00038";
                    }
                }
            }
        }
    } else {
        if (ldMktTpCd === "1") {
            if (korengTpCd === "1") {
                dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=5";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00009";
                } else {
                    rexName = "RLDFIL00016";
                }
            } else {
                dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=6";
                if (stkcertDelistDd > '20050127') {
                    rexName = "RLDFIL00010";
                } else {
                    rexName = "RLDFIL00017";
                }
            }
        } else {
            if (ldMktTpCd === "6") {
                if (korengTpCd === "1") {
                    dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=5";
                    if (stkcertDelistDd > '20050127') {
                        rexName = "RLDFIL00039";
                    } else {
                        rexName = "RLDFIL00040";
                    }
                } else {
                    dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=6";
                    if (stkcertDelistDd > '20050127') {
                        rexName = "RLDFIL00041";
                    } else {
                        rexName = "RLDFIL00042";
                    }
                }
            } else {
                if (korengTpCd === "1") {
                    dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=5";
                    if (stkcertDelistDd > '20050127') {
                        rexName = "RLDFIL00011";
                    } else {
                        rexName = "RLDFIL00018";
                    }
                } else {
                    dataLocation = "/issue/reportPrint.do?method=searchListNewCertificate&listCertApplId=" + listCertApplId + "&bycertSeq=" + bycertSeq + "&reportDiv=6";
                    if (stkcertDelistDd > '20050127') {
                        rexName = "RLDFIL00012";
                    } else {
                        rexName = "RLDFIL00019";
                    }
                }
            }
        }
    }
    $.ajax({ type: "POST", async: false, url: dataLocation, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                $c.util.getComponent('dma_SearchDetailReq').set('ncertSeq', result.certSeq);
                $c.util.getComponent('dma_SearchDetailReq').set('ncomNm', result.comNm);
                $c.util.getComponent('dma_SearchDetailReq').set('nlistCertUseContn', result.listCertUseContn);
                $c.util.getComponent('dma_SearchDetailReq').set('ntoday', result.today);
                $c.util.getComponent('dma_SearchDetailReq').set('nindNm', result.indNm);
                $c.util.getComponent('dma_SearchDetailReq').set('nlistNo', result.listNo);
                $c.util.getComponent('dma_SearchDetailReq').set('nceoNm', result.ceoNm);
                $c.util.getComponent('dma_SearchDetailReq').set('ncurrIsoCd', result.currIsoCd);
                $c.util.getComponent('dma_SearchDetailReq').set('nldMktTpCd', result.ldMktTpCd);
                $c.util.getComponent('dma_SearchDetailReq').set('nTempleteCd', rexName);
                if (!isNaN(result.listCmstkShrs)) {
                    let len_listCmstkShrs, point_listCmstkShrs, comma_plus_listCmstkShrs;
                    let simple_listCmstkShrs = result.listCmstkShrs;
                    len_listCmstkShrs = simple_listCmstkShrs.length;
                    simple_listCmstkShrs = simple_listCmstkShrs + "";
                    point_listCmstkShrs = len_listCmstkShrs % 3;
                    comma_plus_listCmstkShrs = simple_listCmstkShrs.substring(0, point_listCmstkShrs);
                    while (point_listCmstkShrs < len_listCmstkShrs) {
                        if (comma_plus_listCmstkShrs !== "") {
                            comma_plus_listCmstkShrs += ",";
                        }
                        comma_plus_listCmstkShrs += simple_listCmstkShrs.substring(point_listCmstkShrs, point_listCmstkShrs + 3);
                        point_listCmstkShrs += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nlistCmstkShrs', comma_plus_listCmstkShrs);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nlistCmstkShrs', result.listCmstkShrs);
                }
                if (!isNaN(result.listPrefstkShrs)) {
                    let len_listPrefstkShrs, point_listPrefstkShrs, comma_plus_listPrefstkShrs;
                    let simple_listPrefstkShrs = result.listPrefstkShrs;
                    len_listPrefstkShrs = simple_listPrefstkShrs.length;
                    simple_listPrefstkShrs = simple_listPrefstkShrs + "";
                    point_listPrefstkShrs = len_listPrefstkShrs % 3;
                    comma_plus_listPrefstkShrs = simple_listPrefstkShrs.substring(0, point_listPrefstkShrs);
                    while (point_listPrefstkShrs < len_listPrefstkShrs) {
                        if (comma_plus_listPrefstkShrs !== "") {
                            comma_plus_listPrefstkShrs += ",";
                        }
                        comma_plus_listPrefstkShrs += simple_listPrefstkShrs.substring(point_listPrefstkShrs, point_listPrefstkShrs + 3);
                        point_listPrefstkShrs += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nlistPrefstkShrs', comma_plus_listPrefstkShrs);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nlistPrefstkShrs', result.listPrefstkShrs);
                }
                if (!isNaN(result.parval)) {
                    let len_parval, point_parval, comma_plus_parval;
                    let simple_parval = result.parval;
                    len_parval = simple_parval.length;
                    simple_parval = simple_parval + "";
                    point_parval = len_parval % 3;
                    comma_plus_parval = simple_parval.substring(0, point_parval);
                    while (point_parval < len_parval) {
                        if (comma_plus_parval !== "") {
                            comma_plus_parval += ",";
                        }
                        comma_plus_parval += simple_parval.substring(point_parval, point_parval + 3);
                        point_parval += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('nparval', comma_plus_parval);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nparval', result.parval);
                }
                if (!isNaN(result.cap)) {
                    let len_cap, point_cap, comma_plus_cap;
                    let simple_cap = result.cap;
                    len_cap = simple_cap.length;
                    simple_cap = simple_cap + "";
                    point_cap = len_cap % 3;
                    comma_plus_cap = simple_cap.substring(0, point_cap);
                    while (point_cap < len_cap) {
                        if (comma_plus_cap !== "") {
                            comma_plus_cap += ",";
                        }
                        comma_plus_cap += simple_cap.substring(point_cap, point_cap + 3);
                        point_cap += 3;
                    }
                    $c.util.getComponent('dma_SearchDetailReq').set('ncap', comma_plus_cap);
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('ncap', result.cap);
                }
                if (!isNaN(result.listDd)) {
                    let sub_printDate = result.listDd;
                    let sub_printDate_Y = "";
                    let sub_printDate_M = "";
                    let sub_printDate_D = "";
                    switch (rexName) {
                        case 'RLDFIL00014':

                        case 'RLDFIL00010':

                        case 'RLDFIL00017':

                        case 'RLDFIL00038':

                        case 'RLDFIL00041':

                        case 'RLDFIL00042':

                        case 'RLDFIL00012':

                        case 'RLDFIL00019':
                        sub_printDate_M = sub_printDate.substring(0, 2);
                        sub_printDate_D = sub_printDate.substring(2, 4);
                        sub_printDate_Y = sub_printDate.substring(4, 8);
                        break;
                        default:
                        sub_printDate_Y = sub_printDate.substring(0, 4);
                        sub_printDate_M = sub_printDate.substring(4, 6);
                        sub_printDate_D = sub_printDate.substring(6, 8);
                        break;
                    }
                    switch (rexName) {
                        case 'RLDFIL00006':

                        case 'RLDFIL00014':
                        $c.util.getComponent('dma_SearchDetailReq').set('nlistDd', sub_printDate_Y + ". " + sub_printDate_M + ". " + sub_printDate_D);
                        break;
                        case 'RLDFIL00038':

                        case 'RLDFIL00010':

                        case 'RLDFIL00017':

                        case 'RLDFIL00041':

                        case 'RLDFIL00042':

                        case 'RLDFIL00012':

                        case 'RLDFIL00019':
                        $c.util.getComponent('dma_SearchDetailReq').set('nlistDd', sub_printDate_M + ". " + sub_printDate_D + ". " + sub_printDate_Y);
                        break;
                        default:
                        $c.util.getComponent('dma_SearchDetailReq').set('nlistDd', sub_printDate_Y + "년 " + sub_printDate_M + "월 " + sub_printDate_D + "일");
                        break;
                    }
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nlistDd', result.listDd);
                }
                if (!isNaN(result.stkcertDelistDd)) {
                    sub_printDate = result.stkcertDelistDd;
                    sub_printDate_Y = "";
                    sub_printDate_M = "";
                    sub_printDate_D = "";
                    switch (rexName) {
                        case 'RLDFIL00010':

                        case 'RLDFIL00017':

                        case 'RLDFIL00041':

                        case 'RLDFIL00042':

                        case 'RLDFIL00012':

                        case 'RLDFIL00019':
                        sub_printDate_M = sub_printDate.substring(0, 2);
                        sub_printDate_D = sub_printDate.substring(2, 4);
                        sub_printDate_Y = sub_printDate.substring(4, 8);
                        break;
                        default:
                        sub_printDate_Y = sub_printDate.substring(0, 4);
                        sub_printDate_M = sub_printDate.substring(4, 6);
                        sub_printDate_D = sub_printDate.substring(6, 8);
                        break;
                    }
                    switch (rexName) {
                        case 'RLDFIL00010':

                        case 'RLDFIL00017':

                        case 'RLDFIL00041':

                        case 'RLDFIL00042':

                        case 'RLDFIL00012':

                        case 'RLDFIL00019':
                        $c.util.getComponent('dma_SearchDetailReq').set('nstkcertDelistDd', sub_printDate_M + ". " + sub_printDate_D + ". " + sub_printDate_Y);
                        break;
                        default:
                        $c.util.getComponent('dma_SearchDetailReq').set('nstkcertDelistDd', sub_printDate_Y + "년 " + sub_printDate_M + "월 " + sub_printDate_D + "일");
                        break;
                    }
                } else {
                    $c.util.getComponent('dma_SearchDetailReq').set('nstkcertDelistDd', result.stkcertDelistDd);
                }
                await scwin.tx_fn_SearchDetail();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};
